mapper.select:
select id, agent_id, task_id, send_queue_depth, send_queue_peak_depth, send_queue_capacity,
       send_queue_utilization_pct, send_queue_avg_wait_ms, retry_queue_depth, retry_queue_peak_depth,
       retry_next_schedule_time, processing_rate_per_sec, success_rate_pct, congestion_level,
       is_congested, congestion_reason, snapshot_time
from agent_queue_snapshot
where agent_id = #{agentId}
 and snapshot_time >= #{from}
 and snapshot_time <= #{to}
order by snapshot_time asc
